const productsInput = $('2. خدمة المنتجات (Products Service)').all();
const warehouseInput = $('3. خدمة المستودعات (Warehouse Service)').all();

const products = productsInput.map(p => p.json);
const inventory = warehouseInput.map(i => i.json);

const lowStock = [];
const outOfStock = [];

for (const p of products) {
  const qty = Number(p.stock_quantity ?? p.stock ?? 0);
  if (qty === 0) {
    outOfStock.push({ id: p.id, name: p.name_ar || p.name, stock: 0, price: p.price_lyd || p.price });
  } else if (qty < 20) {
    lowStock.push({ id: p.id, name: p.name_ar || p.name, stock: qty, price: p.price_lyd || p.price });
  }
}

return [{
  json: {
    totalProducts: products.length,
    outOfStockCount: outOfStock.length,
    lowStockCount: lowStock.length,
    outOfStock,
    lowStock,
    warehouseItemsCount: inventory.length
  }
}];

const ordersInput = $('4. خدمة الطلبات (Orders Service)').all();
const paymentsInput = $('5. خدمة المدفوعات (Payment Service)').all();

const orders = ordersInput.map(o => o.json);
const payments = paymentsInput.map(p => p.json);

let totalRevenue = 0;
let confirmedOrders = 0;
let pendingOrders = 0;
let failedOrders = 0;

for (const ord of orders) {
  const status = (ord.status || '').toUpperCase();
  if (status === 'CONFIRMED' || status === 'COMPLETED') confirmedOrders++;
  else if (status === 'PENDING' || status === 'PROCESSING') pendingOrders++;
  else if (status === 'FAILED' || status === 'REJECTED') failedOrders++;
}

for (const pay of payments) {
  if (pay.status === 'SUCCESS' || pay.status === 'COMPLETED') {
    totalRevenue += Number(pay.amount || 0);
  }
}

return [{
  json: {
    totalOrders: orders.length,
    confirmedOrders,
    pendingOrders,
    failedOrders,
    totalRevenueLYD: totalRevenue.toFixed(2),
    totalTransactions: payments.length
  }
}];

const shippingInput = $('6. خدمة الشحن (Shipping Service)').all();
const tickets = shippingInput.map(t => t.json);

const pendingDelivery = tickets.filter(t => t.status === 'PENDING' || t.status === 'AWAITING_PICKUP');
const inTransit = tickets.filter(t => t.status === 'IN_TRANSIT' || t.status === 'PICKED_UP');
const delivered = tickets.filter(t => t.status === 'DELIVERED');

return [{
  json: {
    totalTickets: tickets.length,
    pendingDeliveryCount: pendingDelivery.length,
    inTransitCount: inTransit.length,
    deliveredCount: delivered.length,
    pendingTickets: pendingDelivery
  }
}];

// استلام مخرجات الخدمات المصغرة وتحليلاتها
const authOutput = $('1. خدمة التوثيق (Auth Service)').all().map(i => i.json);
const productsOutput = $('2. خدمة المنتجات (Products Service)').all().map(i => i.json);
const warehouseOutput = $('3. خدمة المستودعات (Warehouse Service)').all().map(i => i.json);
const ordersOutput = $('4. خدمة الطلبات (Orders Service)').all().map(i => i.json);
const paymentsOutput = $('5. خدمة المدفوعات (Payment Service)').all().map(i => i.json);
const shippingOutput = $('6. خدمة الشحن (Shipping Service)').all().map(i => i.json);
const gatewayOutput = $('7. بوابة الـ API (API Gateway)').all().map(i => i.json);

const detectedErrors = [];
const remediationActions = [];

// 1. فحص صحة خدمة التوثيق
const authData = authOutput[0] || {};
if (!authData.access_token && !authData.token) {
  detectedErrors.push({
    service: 'Auth Service',
    severity: 'HIGH',
    type: 'AUTHENTICATION_FAILURE',
    message: authData.message || 'فشل الحصول على رمز التوثيق JWT من خدمة الهوية',
    statusCode: authData.statusCode || 401
  });
  remediationActions.push({
    action: 'RETRY_AUTH_LOGIN',
    target: 'http://auth-ms:3001/auth/login',
    method: 'POST',
    description: 'إعادة محاولة تسجيل الدخول وإصدار توكن بديل تلقائياً'
  });
}

// 2. فحص صحة وتناسق خدمة المنتجات والمخزون
if (Array.isArray(productsOutput)) {
  for (const item of productsOutput) {
    if (item.error || item.statusCode >= 400) {
      detectedErrors.push({
        service: 'Products Service',
        severity: 'MEDIUM',
        type: 'PRODUCT_FETCH_ERROR',
        message: item.message || 'خطأ في جلب بيانات المنتجات'
      });
      break;
    }
  }
}

// 3. فحص الطلبات العالقة أو الفاشلة التي تحتاج تعافي
if (Array.isArray(ordersOutput)) {
  const pendingOrders = ordersOutput.filter(o => o && o.status === 'PENDING');
  for (const ord of pendingOrders) {
    const hasSuccessfulPayment = Array.isArray(paymentsOutput) && paymentsOutput.some(
      p => (p.orderId === ord.id || p.order_id === ord.id) && (p.status === 'SUCCESS' || p.status === 'COMPLETED')
    );

    const orderCreatedAt = new Date(ord.createdAt || ord.created_at || Date.now()).getTime();
    const isStale = (Date.now() - orderCreatedAt) > (10 * 60 * 1000);

    if (!hasSuccessfulPayment && isStale) {
      detectedErrors.push({
        service: 'Orders Service',
        severity: 'MEDIUM',
        type: 'STUCK_UNPAID_ORDER',
        orderId: ord.id,
        message: `الطلب رقم #${ord.id} معلق بدون دفع لأكثر من 10 دقائق ويحجز المخزون`
      });
      remediationActions.push({
        action: 'AUTO_CANCEL_STUCK_ORDER',
        orderId: ord.id,
        target: `http://orders-ms:3003/api/orders/${ord.id}/fail`,
        method: 'POST',
        description: `إلغاء الطلب #${ord.id} تلقائياً وإعادة الكميات المحجوزة للمخزون`
      });
    }
  }
}

// 4. فحص الشحنات المعلقة بدون سائق
if (Array.isArray(shippingOutput)) {
  const unassignedTickets = shippingOutput.filter(
    t => t && (t.status === 'PENDING' || t.status === 'AWAITING_PICKUP') && !t.driverName && !t.driver_name
  );
  for (const ticket of unassignedTickets) {
    detectedErrors.push({
      service: 'Shipping Service',
      severity: 'LOW',
      type: 'UNASSIGNED_DELIVERY_TICKET',
      ticketId: ticket.id,
      message: `بوليصة الشحن رقم #${ticket.id} جاهزة بدون سائق توصيل معين`
    });
    remediationActions.push({
      action: 'AUTO_ASSIGN_DEFAULT_DRIVER',
      ticketId: ticket.id,
      target: `http://shipping-ms:3006/api/shipping/${ticket.id}/status`,
      method: 'PATCH',
      body: { status: 'PICKED_UP', driverName: 'سائق الدعم الذاتي الآلي' },
      description: `تعيين سائق التوزيع الآلي للبوليصة #${ticket.id} وبدء التوصيل`
    });
  }
}

// 5. فحص حالة بوابة الـ Gateway
if (gatewayOutput.length > 0 && (gatewayOutput[0].statusCode >= 500 || gatewayOutput[0].error)) {
  detectedErrors.push({
    service: 'API Gateway',
    severity: 'CRITICAL',
    type: 'GATEWAY_DEGRADED',
    message: gatewayOutput[0].message || 'بوابة الـ API Gateway غير مستجيبة أو Circuit Breaker مفتوح'
  });
  remediationActions.push({
    action: 'ESCALATE_ALERT',
    target: 'DevOps / Admin',
    description: 'إصدار تنبيه عاجل للتدخل الفوري لإعادة فحص بوابة الـ Gateway'
  });
}

const diagnosisSummary = {
  totalErrorsFound: detectedErrors.length,
  totalActionsPlanned: remediationActions.length,
  healthStatus: detectedErrors.length === 0 ? 'HEALTHY_GREEN' : (detectedErrors.some(e => e.severity === 'CRITICAL') ? 'CRITICAL_RED' : 'WARNING_YELLOW'),
  detectedErrors,
  remediationActions,
  diagnosedAt: new Date().toISOString()
};

return [{ json: diagnosisSummary }];

const diagnosis = $('🤖 وكيل استكشاف وتشخيص الأخطاء (Error Discovery & Diagnostic Agent)').first().json;
const actions = diagnosis.remediationActions || [];
const executionLogs = [];
let healedCount = 0;
let failedActionCount = 0;

for (const act of actions) {
  try {
    if (act.action === 'AUTO_CANCEL_STUCK_ORDER' && act.target) {
      console.log(`[Agent Self-Healing] Executing: ${act.description}`);
      const res = await fetch(act.target, { method: act.method || 'POST' });
      if (res.ok) {
        healedCount++;
        executionLogs.push({
          action: act.action,
          status: 'SUCCESS',
          target: act.target,
          message: `تم إلغاء الطلب #${act.orderId} بنجاح وتحرير مخزونه المرتبط`
        });
      } else {
        failedActionCount++;
        executionLogs.push({
          action: act.action,
          status: 'FAILED',
          statusCode: res.status,
          message: `تعذر تنفيذ الإلغاء: ${res.statusText}`
        });
      }
    } else if (act.action === 'AUTO_ASSIGN_DEFAULT_DRIVER' && act.target) {
      console.log(`[Agent Self-Healing] Executing: ${act.description}`);
      const res = await fetch(act.target, {
        method: act.method || 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(act.body)
      });
      if (res.ok) {
        healedCount++;
        executionLogs.push({
          action: act.action,
          status: 'SUCCESS',
          target: act.target,
          message: `تم تعيين سائق آلي للبوليصة #${act.ticketId} بنجاح`
        });
      } else {
        failedActionCount++;
        executionLogs.push({
          action: act.action,
          status: 'FAILED',
          statusCode: res.status,
          message: `تعذر تعيين السائق: ${res.statusText}`
        });
      }
    } else if (act.action === 'RETRY_AUTH_LOGIN') {
      healedCount++;
      executionLogs.push({
        action: act.action,
        status: 'SCHEDULED',
        message: 'تمت جدولة تجديد رمز الدخول في الدورة القادمة'
      });
    } else {
      executionLogs.push({
        action: act.action,
        status: 'ESCALATED',
        message: act.description
      });
    }
  } catch (err) {
    failedActionCount++;
    executionLogs.push({
      action: act.action,
      status: 'EXCEPTION',
      error: err.message
    });
  }
}

return [{
  json: {
    healedCount,
    failedActionCount,
    totalPlanned: actions.length,
    executionLogs,
    isSelfHealed: healedCount > 0,
    timestamp: new Date().toISOString()
  }
}];

const stockData = $('تحليل المنتجات والمخزون').first().json;
const financeData = $('تحليل الطلبات والمدفوعات').first().json;
const logisticsData = $('تحليل الشحن والعمليات اللوجستية').first().json;
const diagnosticData = $('🤖 وكيل استكشاف وتشخيص الأخطاء (Error Discovery & Diagnostic Agent)').first().json;
const remediationData = $('⚡ وكيل المعالجة والتعافي الذاتي (Autonomous Remediation Executor)').first().json;

const dateStr = new Date().toLocaleString('ar-LY', { timeZone: 'Africa/Tripoli' });

let agentReport = '';
if (diagnosticData.totalErrorsFound === 0) {
  agentReport = `✅ **وكيل استكشاف الأخطاء والتعافي الذاتي:**\n• فحص المنظومة: لم يتم العثور على أخطاء أو تعليق في العمليات 🟢\n• حالة الخدمات: جميع الخدمات الـ 8 متصلة وتعمل بكفاءة 100%`;
} else {
  agentReport = `🤖 **تقرير وكيل الاستكشاف والمعالجة الذاتية (Self-Healing Agent):**\n` +
    `• الأخطاء والمشاكل المكتشفة: ${diagnosticData.totalErrorsFound} مشكلة ⚠️\n` +
    `• الإجراءات المنفذة للتعافي الذاتي: ${remediationData.healedCount} إجراء آلي 🛠️\n` +
    (remediationData.executionLogs.length > 0 ? remediationData.executionLogs.map(l => `  - [${l.status}] ${l.message}`).join('\n') : '') +
    (diagnosticData.detectedErrors.length > 0 ? `\n• تفاصيل المشاكل المكتشفة:\n` + diagnosticData.detectedErrors.map(e => `  - [${e.severity}] [${e.service}]: ${e.message}`).join('\n') : '');
}

const report = `
🏪 **التقرير التنفيذي الموحد لمنظومة الخدمات المصغرة (MicroShop)**
📅 التاريخ: ${dateStr}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

${agentReport}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
💰 **المبيعات والمالية (Orders & Payments):**
• إجمالي الطلبات المسجلة: ${financeData.totalOrders} طلب
• الطلبات المؤكدة: ${financeData.confirmedOrders} ✅
• الطلبات المعلقة: ${financeData.pendingOrders} ⏳
• إجمالي الإيرادات المحصلة: ${financeData.totalRevenueLYD} د.ل

📦 **حالة المنتجات والمخزون (Products & Warehouse):**
• إجمالي المنتجات: ${stockData.totalProducts}
• منتجات نفدت بالكامل: ${stockData.outOfStockCount} 🚨
• منتجات أوشكت على النفاد (< 20): ${stockData.lowStockCount} ⚠️
${stockData.lowStock.length > 0 ? stockData.lowStock.map(p => `  - ${p.name}: متبقي (${p.stock}) بسعر ${p.price} د.ل`).join('\n') : '  - المخزون بحالة ممتازة ✅'}

🚚 **الشحن والعمليات اللوجستية (Shipping & Drivers):**
• إجمالي بوالص الشحن: ${logisticsData.totalTickets}
• بوالص بانتظار الاستلام: ${logisticsData.pendingDeliveryCount} ⏳
• شحنات قيد التوصيل الآن: ${logisticsData.inTransitCount} 🛵
• شحنات تم تسليمها بنجاح: ${logisticsData.deliveredCount} 🎉

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🌐 حالة بوابة الـ Gateway وجميع الخدمات المصغرة (8 Services): تعمل بنجاح 🟢
`;

return [{
  json: {
    report,
    agentSummary: {
      diagnostic: diagnosticData,
      remediation: remediationData
    },
    summary: {
      stock: stockData,
      finance: financeData,
      logistics: logisticsData
    },
    timestamp: new Date().toISOString()
  }
}];

const reportData = $('توليد التقرير التنفيذي الشامل (مع تقرير التعافي الذاتي)').first().json;

// جاهز للربط مع Telegram Bot أو Discord Webhook أو Email Mailer
console.log('--- MICROSHOP EXECUTIVE REPORT WITH SELF-HEALING AGENT ---');
console.log(reportData.report);

return [{
  json: {
    status: 'SUCCESS',
    message: 'تم تدقيق جميع الخدمات المصغرة، فحص الأخطاء، معالجتها وتجهيز التقرير التنفيذي بنجاح',
    report: reportData.report,
    agentSummary: reportData.agentSummary
  }
}];
